<h1>Public menu manager</h1><p>Create, hide, archive, nest one level, and reorder tenant-owned public links. The ordering island enhances the usable server-rendered fallback.</p><?php foreach(session('errors')??[] as $error): ?><p><?= esc($error) ?></p><?php endforeach ?>
<form method="post" action="<?= site_url('tenant/website/menu') ?>"><?= csrf_field() ?><?php if($selected): ?><input type="hidden" name="id" value="<?= esc($selected['id']) ?>"><?php endif ?><label>Label <input name="label" required value="<?= esc(old('label',$selected['label']??'')) ?>"></label><label>Parent <select name="parent_id"><option value="">Top level</option><?php foreach($items as $item): ?><?php if($item['parent_id']===null): ?><option value="<?= esc($item['id']) ?>"<?= (int)old('parent_id',$selected['parent_id']??0)===(int)$item['id']?' selected':'' ?>><?= esc($item['label']) ?></option><?php endif ?><?php endforeach ?></select></label><label>Link type <select name="link_type"><option>route</option><option<?= old('link_type',$selected['link_type']??'route')==='external'?' selected':'' ?>>external</option></select></label><label>Route <select name="route_name"><?php foreach(['home','about','contact','departments','programmes','admissions','news','announcements','calendar','management','gallery'] as $route): ?><option<?= old('route_name',$selected['route_name']??'home')===$route?' selected':'' ?>><?= esc($route) ?></option><?php endforeach ?></select></label><label>External URL <input name="url" value="<?= esc(old('url',$selected['url']??'')) ?>"></label><label>Target <select name="target"><option>_self</option><option<?= old('target',$selected['target']??'_self')==='_blank'?' selected':'' ?>>_blank</option></select></label><label>Order <input name="sort_order" type="number" value="<?= esc(old('sort_order',$selected['sort_order']??0)) ?>"></label><input type="hidden" name="status" value="active"><label><input type="checkbox" name="is_visible" value="1"<?= old('is_visible',$selected['is_visible']??1)?' checked':'' ?>> Visible</label><button>Save menu item</button></form>
<h2>Current links</h2><ul><?php foreach($items as $item): ?><li><a href="?id=<?= esc($item['id']) ?>"><?= esc($item['label']) ?></a> — <?= esc($item['status']) ?><form class="inline-form" method="post" action="<?= site_url('tenant/website/menu/'.$item['id'].'/archive') ?>"><?= csrf_field() ?><button>Archive</button></form></li><?php endforeach ?></ul>
<div id="website-menu-manager" data-endpoint="<?= site_url('tenant/website/menu/reorder') ?>" data-csrf-header="<?= esc(csrf_header()) ?>" data-csrf-token="<?= esc(csrf_hash()) ?>"><h2>Enhanced ordering</h2><p data-loading>Loading ordering controls…</p></div><script type="application/json" id="website-menu-items"><?= json_encode(array_map(static fn(array $item):array=>['id'=>(int)$item['id'],'label'=>$item['label']],$items),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
<noscript><form method="post" action="<?= site_url('tenant/website/menu/reorder') ?>"><?= csrf_field() ?><?php foreach($items as $item): ?><label><?= esc($item['label']) ?> <input name="item_ids[]" value="<?= esc($item['id']) ?>"></label><?php endforeach ?><button>Save displayed order</button></form></noscript><script type="module" src="<?= base_url('assets/js/website-menu-manager.js') ?>"></script><?= $this->endSection() ?>
